public:
    int compareVersion(string version1, string version2) {
        int i = 0, j = 0;
        int n1 = version1.size(), n2 = version2.size();
        while (i < n1 || j < n2) {
            long long val1 = 0, val2 = 0;
            while (i < n1 && version1[i] != '.') {
                val1 = val1 * 10 + (version1[i] - '0');
                i++;
            }
            while (j < n2 && version2[j] != '.') {
                val2 = val2 * 10 + (version2[j] - '0');
                j++;
            }
            if (val1 < val2) return -1;
            if (val1 > val2) return 1;
            if (i < n1 && version1[i] == '.') i++;
            if (j < n2 && version2[j] == '.') j++;
        }
        return 0;
    }
};

class Solution {
    public int compareVersion(String version1, String version2) {
        int i = 0, j = 0;
        int n1 = version1.length(), n2 = version2.length();
        while (i < n1 || j < n2) {
            long val1 = 0, val2 = 0;
            while (i < n1 && version1.charAt(i) != '.') {
                val1 = val1 * 10 + (version1.charAt(i) - '0');
                i++;
            }
            while (j < n2 && version2.charAt(j) != '.') {
                val2 = val2 * 10 + (version2.charAt(j) - '0');
                j++;
            }
            if (val1 < val2) return -1;
            if (val1 > val2) return 1;
            if (i < n1 && version1.charAt(i) == '.') i++;
            if (j < n2 && version2.charAt(j) == '.') j++;
        }
        return 0;
    }
}

var compareVersion = function(version1, version2) {
    const v1 = version1.split('.').map(Number);
    const v2 = version2.split('.').map(Number);
    const maxLen = Math.max(v1.length, v2.length);
    for (let i = 0; i < maxLen; i++) {
        const val1 = i < v1.length ? v1[i] : 0;
        const val2 = i < v2.length ? v2[i] : 0;
        if (val1 < val2) return -1;
        if (val1 > val2) return 1;
    }
    return 0;
};
